"""Reference-motion library generated by this project (no third-party motion data).

Every clip is made with the robot's own controllers or kinematics, so it is free of licence questions and
physically sensible for this body:

    walk        one stride (two steps) of the model-based WalkController walking straight, recorded from the
                physics simulation at 200 Hz and resampled to ~50 Hz, closed into a loop whose root advances
                by the stride every period
    walk_turn   the same while turning (forward speed + yaw rate)
    stand       the walker's balanced standing pose (knees slightly bent), recorded after settling
    wave        the walker standing while the ArmController's "wave" gesture runs on the right arm
                (joint-space minimum-jerk keyframes, recorded in physics)
    reach       both hands reaching to points in front of the chest with the ArmController's damped-least-
                squares arm IK, then returning home (recorded in physics)
    squat       kinematic: pelvis down 0.2 leg lengths and back up with the legs from closed-form leg IK
                (control/walk_ik.py), feet fixed, the whole-body centre of mass kept over the middle of the
                soles, torso leaning and arms reaching forward as counterweight
    sway        kinematic "dance": side-to-side weight shift with knee bounces, a torso twist and
                alternating arm raises, centre of mass inside the support polygon

Physics-recorded clips use a fresh copy of the model and the same control composition as the live session
(walker every 5 ms, arm controller every 20 ms). Kinematic clips are quasi-static (slow, CoM over the feet).

    python -m simulatics.imitate.library             rebuild every clip into simulatics/imitate/motions/
    python -m simulatics.imitate.library walk squat  rebuild some
"""
from __future__ import annotations

import json
import sys
import time
from pathlib import Path

import mujoco
import numpy as np

from .motion import Motion, is_motion_file, quat_slerp

LIBRARY_DIR = Path(__file__).resolve().parent / "motions"
CLIPS = ("walk", "walk_turn", "stand", "wave", "reach", "squat", "sway")
FPS = 50.0


# =========================================================================================================
# Lookup
# =========================================================================================================
def library_path(name: str) -> Path:
    return LIBRARY_DIR / f"{name}.npz"


def list_motions(extra_dirs: list[str | Path] | None = None) -> list[dict]:
    """Motions in the library (and in extra_dirs): [{"name", "path", "frames", "fps", "duration_s", "loop",
    "source", "library"}]. Unreadable files are skipped."""
    out = []
    dirs = [(LIBRARY_DIR, True)] + [(Path(d), False) for d in (extra_dirs or [])]
    for d, lib in dirs:
        if not d.is_dir():
            continue
        for p in sorted(d.glob("*.npz")):
            if p.name.endswith(".tmp.npz") or not is_motion_file(p):
                continue
            try:
                m = Motion.load(p)
            except Exception:  # noqa: BLE001 - a broken file should not hide the others
                continue
            out.append({**m.summary(), "path": str(p), "library": lib})
    return out


def load_motion(name_or_path: str | Path) -> Motion:
    """A library clip by name ("walk") or any motion .npz by path."""
    p = Path(name_or_path)
    if p.suffix == ".npz" and p.exists():
        return Motion.load(p)
    lib = library_path(str(name_or_path))
    if lib.exists():
        return Motion.load(lib)
    sample = Path(__file__).resolve().parent.parent / "samples" / "data" / f"{name_or_path}.npz"
    if sample.exists():          # a motion-capture reference clip (simulatics/samples), e.g. "backflip"
        return Motion.load(sample)
    raise FileNotFoundError(f"no motion {name_or_path!r} (library clips: {', '.join(CLIPS)})")


# =========================================================================================================
# Recording helpers
# =========================================================================================================
def default_model() -> mujoco.MjModel:
    from ..models import HumanoidParams, build_mjcf
    return mujoco.MjModel.from_xml_string(build_mjcf(HumanoidParams()))


class _Rig:
    """Walker (+ arm controller) on a fresh MjData, ticked like the live session."""

    def __init__(self, model: mujoco.MjModel, arms: bool = False):
        from ..control.walker import WalkController
        self.model = model
        self.data = mujoco.MjData(model)
        if model.nkey > 0:
            mujoco.mj_resetDataKeyframe(model, self.data, 0)
        mujoco.mj_forward(model, self.data)
        self.walker = WalkController(model)
        self.walker.reset(model, self.data)
        self.arms = None
        if arms:
            from ..control.arms import ArmController
            self.arms = ArmController(model, self.data)
        self.ticks = 0
        self.every = 1
        if self.arms is not None:
            self.every = max(1, int(round(self.arms.control_dt / self.walker.control_dt)))
        self.qpos: list[np.ndarray] = []

    @property
    def dt(self) -> float:
        return self.walker.control_dt

    def tick(self, record: bool = True) -> None:
        m, d = self.model, self.data
        self.walker.step(m, d)
        self.ticks += 1
        if self.arms is not None and self.ticks % self.every == 0:
            self.arms.step(m, d)
        mujoco.mj_step(m, d, self.walker.substeps)
        if self.walker.mode == "fallen" or not np.isfinite(d.qpos).all():
            raise RuntimeError("the robot fell while recording a reference motion")
        if record:
            self.qpos.append(d.qpos.copy())

    def run(self, seconds: float, record: bool = True) -> None:
        for _ in range(int(round(seconds / self.dt))):
            self.tick(record)


def _resample_ticks(model: mujoco.MjModel, qpos: np.ndarray, dt: float, fps: float, t0: float = 0.0,
                    t1: float | None = None, n: int | None = None) -> tuple[np.ndarray, float]:
    """Interpolate a qpos trajectory sampled every dt (rows) at n + 1 evenly spaced times in [t0, t1]
    (default n = round((t1 - t0) fps)). Returns (qpos (n + 1, nq), effective fps n / (t1 - t0))."""
    from .motion import free_root
    _, qa, _ = free_root(model)
    t1 = (len(qpos) - 1) * dt if t1 is None else t1
    n = max(2, int(round((t1 - t0) * fps))) if n is None else n
    times = np.linspace(t0, t1, n + 1)
    f = np.clip(times / dt, 0, len(qpos) - 1)
    i0 = np.minimum(np.floor(f).astype(int), len(qpos) - 2)
    a = f - i0
    out = qpos[i0] + (qpos[i0 + 1] - qpos[i0]) * a[:, None]
    out[:, qa + 3:qa + 7] = quat_slerp(qpos[i0, qa + 3:qa + 7], qpos[i0 + 1, qa + 3:qa + 7], a)
    return out, n / (t1 - t0)


# =========================================================================================================
# Clips
# =========================================================================================================
def record_walk(model: mujoco.MjModel, speed_frac: float = 0.8, yaw_rate: float = 0.0, warmup_steps: int = 6,
                name: str = "walk") -> Motion:
    """One steady-state stride of WalkController under a velocity command, closed into a loop.

    The stride is cut between two consecutive lift-offs of the left foot (2 x (single + double support)
    walker ticks, at 200 Hz) and resampled to ~50 Hz with that period kept exactly."""
    from ..control.walk_footsteps import LEFT
    rig = _Rig(model)
    rig.run(0.5, record=False)
    w = rig.walker
    vx = speed_frac * w.walk_speed
    w.set_velocity(vx, 0.0, yaw_rate)
    starts, last = [], None
    qs = []
    k = 0
    limit = int(60.0 / rig.dt)
    while len(starts) < warmup_steps // 2 + 2 and k < limit:
        rig.tick(record=False)
        qs.append(rig.data.qpos.copy())
        sw = w.swing
        if sw is not None and sw is not last and sw.side == LEFT:
            starts.append(k)
        last = sw
        k += 1
    if len(starts) < 2:
        raise RuntimeError("the walker did not reach a steady gait")
    a, b = starts[-2], starts[-1]
    seg = np.array(qs[a:b + 1])
    q, fps = _resample_ticks(model, seg, rig.dt, FPS)
    meta = {"source": f"WalkController velocity command vx={vx:.3f} m/s, wz={yaw_rate:.3f} rad/s, recorded "
                      f"in physics at {1 / rig.dt:.0f} Hz", "speed_mps": vx, "yaw_rate": yaw_rate,
            "stride_s": (b - a) * rig.dt}
    return Motion.from_cycle(model, q, fps, name=name, meta=meta)


def stand_pose(model: mujoco.MjModel, settle_s: float = 1.5) -> np.ndarray:
    """qpos of the walker's balanced stand after settling (velocities zero)."""
    rig = _Rig(model)
    rig.run(settle_s, record=False)
    return rig.data.qpos.copy()


def record_stand(model: mujoco.MjModel, name: str = "stand") -> Motion:
    q = stand_pose(model)
    qs = np.tile(q, (26, 1))
    return Motion.from_cycle(model, qs, FPS, name=name, stationary=True,
                             meta={"source": "WalkController balanced stand, settled 1.5 s in physics"})


def _record_arm_clip(model: mujoco.MjModel, commands, name: str, tail_s: float = 0.6, max_s: float = 20.0,
                     source: str = "") -> Motion:
    """Walker standing + ArmController commands issued in sequence (each when the previous one finished)."""
    rig = _Rig(model, arms=True)
    rig.run(1.0, record=False)
    rig.qpos.clear()
    t, pending = 0.0, list(commands)
    rig.run(0.1)
    while (pending or rig.arms.busy) and t < max_s:
        if pending and not rig.arms.busy:
            for side, skill, kw in pending.pop(0):
                msg = rig.arms.command(side, skill, **kw)
                if "unknown" in msg or "no arm" in msg:
                    raise RuntimeError(msg)
            rig.run(0.06)     # let the arm start moving before checking busy again
        rig.run(0.02)
        t += 0.02
    rig.run(tail_s)
    q, fps = _resample_ticks(model, np.array(rig.qpos), rig.dt, FPS)
    return Motion.from_cycle(model, q, fps, name=name, stationary=True, meta={"source": source})


def record_wave(model: mujoco.MjModel) -> Motion:
    return _record_arm_clip(model, [[("right", "wave", {})]], "wave",
                            source="WalkController stand + ArmController 'wave' on the right arm, physics")


def record_reach(model: mujoco.MjModel) -> Motion:
    c = stand_pose(model)[:3]                   # torso centre of the balanced stand
    cmds = [[("left", "reach", {"target": (c + [0.36, 0.16, 0.02]).tolist()}),
             ("right", "reach", {"target": (c + [0.36, -0.16, 0.02]).tolist()})],
            [("both", "home", {})],
            [("left", "reach", {"target": (c + [0.30, 0.22, -0.22]).tolist()}),
             ("right", "reach", {"target": (c + [0.30, -0.22, -0.22]).tolist()})],
            [("both", "home", {})]]
    return _record_arm_clip(model, cmds, "reach",
                            source="WalkController stand + ArmController DLS-IK reaches (both hands), physics")


class _LegKinematics:
    """Quasi-static whole-body poses from the walker's closed-form leg IK with fixed feet."""

    def __init__(self, model: mujoco.MjModel, stand: np.ndarray):
        from ..control.walk_ik import LEG_JOINTS, SIDES, RobotGeometry
        self.model, self.geo = model, RobotGeometry.from_model(model)
        self.d = mujoco.MjData(model)
        self.stand = stand.copy()
        self.d.qpos[:] = stand
        mujoco.mj_kinematics(model, self.d)
        self.sides = SIDES
        self.leg_adr = {s: np.array([model.jnt_qposadr[model.joint(f"{s}_{j}").id] for j in LEG_JOINTS])
                        for s in SIDES}
        self.ab_adr = np.array([model.jnt_qposadr[model.joint(n).id] for n in ("abdomen_y", "abdomen_x")])
        # sole poses (world) of the stand
        self.feet = {}
        for s in SIDES:
            b = model.body(f"{s}_foot").id
            R = self.d.xmat[b].reshape(3, 3).copy()
            self.feet[s] = (self.d.xpos[b] + R @ self.geo.legs[s].sole, R)
        self.torso = model.body("torso").id
        self.mid = (self.feet["left"][0] + self.feet["right"][0]) / 2

    def joint(self, name: str) -> int:
        return int(self.model.jnt_qposadr[self.model.joint(name).id])

    def pose(self, com_xy: np.ndarray, z_torso: float, rpy: tuple[float, float, float],
             joints: dict[str, float]) -> np.ndarray:
        """Torso at height z_torso with roll/pitch/yaw rpy, abdomen at 0, legs solved to the fixed feet,
        extra joint values applied, torso xy iterated until the whole-body CoM xy is com_xy."""
        from ..control.walk_ik import leg_ik, rot_x, rot_y, rot_z
        m, d = self.model, self.d
        R = rot_z(rpy[2]) @ rot_y(rpy[1]) @ rot_x(rpy[0])
        q = self.stand.copy()
        for n, v in joints.items():
            q[self.joint(n)] = v
        q[self.ab_adr] = 0.0
        p = np.array([com_xy[0], com_xy[1], z_torso])
        p[:2] += self.stand[:2] - self.mid[:2]
        from .motion import mat_to_quat
        q[3:7] = mat_to_quat(R)
        for _ in range(8):
            q[0:3] = p
            p_pel = p + R @ self.geo.pelvis
            for s in self.sides:
                pos, Rf = self.feet[s]
                q[self.leg_adr[s]], _ = leg_ik(self.geo.legs[s], p_pel, R, pos, Rf)
            d.qpos[:] = q
            mujoco.mj_kinematics(m, d)
            mujoco.mj_comPos(m, d)
            err = np.asarray(com_xy) - d.subtree_com[self.torso][:2]
            p[:2] += err
            if np.abs(err).max() < 1e-5:
                break
        q[0:3] = p
        return q


def _min_jerk(x):
    x = np.clip(x, 0.0, 1.0)
    return x * x * x * (10 - 15 * x + 6 * x * x)


def make_squat(model: mujoco.MjModel, depth_frac: float = 0.2, period: float = 3.2,
               name: str = "squat") -> Motion:
    stand = stand_pose(model)
    lk = _LegKinematics(model, stand)
    leg = lk.geo.leg_length
    n = int(round(period * FPS))
    qs = []
    for k in range(n + 1):
        t = k / FPS
        ph = t / period                       # 0-0.4 down, 0.4-0.5 hold, 0.5-0.9 up, 0.9-1 hold
        s = _min_jerk(ph / 0.4) if ph < 0.5 else 1.0 - _min_jerk((ph - 0.5) / 0.4)
        q = lk.pose(lk.mid[:2], stand[2] - depth_frac * leg * s, (0.0, 0.28 * s, 0.0),
                    {"left_shoulder_y": -1.1 * s, "right_shoulder_y": -1.1 * s,
                     "left_elbow": -0.25 * s, "right_elbow": -0.25 * s})
        qs.append(q)
    return Motion.from_cycle(model, np.array(qs), FPS, name=name, stationary=True,
                             meta={"source": "kinematic squat: closed-form leg IK, CoM over the soles",
                                   "depth_m": depth_frac * leg})


def make_sway(model: mujoco.MjModel, period: float = 4.0, name: str = "sway") -> Motion:
    stand = stand_pose(model)
    lk = _LegKinematics(model, stand)
    half = abs(lk.feet["left"][0][1] - lk.feet["right"][0][1]) / 2
    n = int(round(period * FPS))
    qs = []
    for k in range(n + 1):
        t = k / FPS
        lat = np.sin(2 * np.pi * t / (period / 2))        # two sways per period
        bounce = 0.5 * (1 - np.cos(2 * np.pi * t / (period / 4)))
        twist = 0.15 * np.sin(2 * np.pi * t / period)
        left_up = max(0.0, lat)
        right_up = max(0.0, -lat)
        com = lk.mid[:2] + np.array([0.0, 0.55 * half * lat])
        q = lk.pose(com, stand[2] - 0.035 * bounce, (0.04 * lat, 0.03 * bounce, twist),
                    {"left_shoulder_x": 0.25 + 0.9 * left_up, "right_shoulder_x": -(0.25 + 0.9 * right_up),
                     "left_shoulder_y": -0.5 * left_up, "right_shoulder_y": -0.5 * right_up,
                     "left_elbow": -0.5 - 0.4 * left_up, "right_elbow": -0.5 - 0.4 * right_up})
        qs.append(q)
    return Motion.from_cycle(model, np.array(qs), FPS, name=name, stationary=True,
                             meta={"source": "kinematic dance: weight shift, knee bounce, torso twist, arm raises; "
                                             "leg IK with CoM inside the support polygon"})


BUILDERS = {
    "walk": lambda m: record_walk(m, 0.8, 0.0, name="walk"),
    "walk_turn": lambda m: record_walk(m, 0.6, 0.25, name="walk_turn"),
    "stand": record_stand,
    "wave": record_wave,
    "reach": record_reach,
    "squat": make_squat,
    "sway": make_sway,
}


def build_library(model: mujoco.MjModel | None = None, names=None, out_dir: str | Path = LIBRARY_DIR,
                  verbose: bool = False) -> dict[str, Path]:
    """(Re)generate library clips into out_dir. Returns name -> path."""
    model = model or default_model()
    out = {}
    for name in names or CLIPS:
        t0 = time.perf_counter()
        m = BUILDERS[name](model)
        p = m.save(Path(out_dir) / f"{name}.npz")
        out[name] = p
        if verbose:
            print(json.dumps({**m.summary(), "kB": round(p.stat().st_size / 1024, 1),
                              "seconds": round(time.perf_counter() - t0, 2)}), flush=True)
    return out


if __name__ == "__main__":
    build_library(names=sys.argv[1:] or None, verbose=True)
